import{_ as o,c as a,o as t,aN as c}from"./chunks/framework.wz1796_d.js";const u=JSON.parse('{"title":"KernelSU自定义修补","description":"KernelSU自定义修补","frontmatter":{"title":"KernelSU自定义修补","description":"KernelSU自定义修补"},"headers":[],"relativePath":"info/zdyksu.md","filePath":"info/zdyksu.md"}'),d={name:"info/zdyksu.md"};function r(i,e,l,s,p,n){return t(),a("div",null,[...e[0]||(e[0]=[c('<h1 id="kernelsu自定义修补模式" tabindex="-1">KernelSU自定义修补模式 <a class="header-anchor" href="#kernelsu自定义修补模式" aria-label="Permalink to &quot;KernelSU自定义修补模式&quot;">​</a></h1><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2><p>经群友反馈，部分<code>Windwos</code>系统可能存在无法使用工具的<code>KernelSU默认修补模式</code>进行修补镜像，造成无法全自动ROOT，我已经在工具<code>5.0.0</code>版本更换了已修复此bug的修补程序，但很可能还有未发现的bug再次造成无法继续修补，进而编写此教程。</p><div class="tip custom-block"><p class="custom-block-title">当前教程适用于以下几种情况</p><ul><li>想刷KernelSU的分支版本。例如<code>MKSU</code>、<code>SukiSU-Ultra</code>、<code>ReSukiSU</code>、<code>KernelSU-Next</code>等其它分支.</li><li>当前系统无法使用<code>KernelSU默认修补模式</code>修补镜像。例如报错<code>找不到修补好的boot文件</code>的情况.</li><li>当前系统使用<code>KernelSU默认修补模式</code>刷入后无法正常开机。常出现于某些<code>联发科</code>处理器的手机上.</li></ul></div><h2 id="_1-修改修补模式" tabindex="-1">1.修改修补模式 <a class="header-anchor" href="#_1-修改修补模式" aria-label="Permalink to &quot;1.修改修补模式&quot;">​</a></h2><p>首先回到工具的主页，输入<code>5</code>，进入<code>自定义配置</code>，在自定义配置之内输入<code>32</code>并回车</p><p><img src="https://pic.dishuo183.top/images/root/2026/01/14/2340410671.png" alt="picture"></p><p>在新出现的页面输入<code>yes</code>并回车确认，启用<code>自定义修补模式</code></p><p><img src="https://pic.dishuo183.top/images/root/2026/01/14/915741589.png" alt="picture"></p><h2 id="_2-重新全自动root" tabindex="-1">2.重新全自动ROOT <a class="header-anchor" href="#_2-重新全自动root" aria-label="Permalink to &quot;2.重新全自动ROOT&quot;">​</a></h2><p>继续打开全自动ROOT的<code>下载卡刷包安装KernelSU</code>，在工具获取完设备信息后，会提示让拖入要修补的管理器，这时候请打开工具当前文件夹内的<code>Download\\AppFiles</code>文件，在之前全自动ROOT失败的时候，工具会自动下载对应安装包到此文件夹内，可直接拖入</p><p><img src="https://pic.dishuo183.top/images/root/2026/01/14/1095377773.png" alt="picture"></p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>若无法拖入可查看 <a href="/info/tr">拖入说明</a></p><p>若文件夹内无安装包文件，可前往工具主页的功能<code>7</code>进行下载，或访问<a href="https://pan.dishuo183.top/%E6%90%9E%E6%9C%BA%E6%96%87%E4%BB%B6%E5%90%88%E9%9B%86/KernelSU%E5%AE%98%E6%96%B9-%E5%88%86%E6%94%AF" target="_blank" rel="noreferrer">个人网盘</a>下载</p></div><h2 id="_3-继续全自动root" tabindex="-1">3.继续全自动ROOT <a class="header-anchor" href="#_3-继续全自动root" aria-label="Permalink to &quot;3.继续全自动ROOT&quot;">​</a></h2><p>在拖入完成之后，工具会自动识别拖入安装包的信息，后续内容就和教程一样，无需手动操作，等待工具全自动运行即可ROOT成功</p><p><img src="https://pic.dishuo183.top/images/root/2026/01/14/2237873545.png" alt="picture"></p><hr><h2 id="补充说明" tabindex="-1">补充说明 <a class="header-anchor" href="#补充说明" aria-label="Permalink to &quot;补充说明&quot;">​</a></h2><p>自定义修补模式除了<code>官方KernelSU</code>，还支持<code>MKSU</code>、<code>SukiSU-Ultra</code>、<code>ReSukiSU</code>、<code>KernelSU-Next</code>这几个版本的修补，可使用相同方式刷入ROOT，只支持<code>LKM</code>模式哦</p>',19)])])}const S=o(d,[["render",r]]);export{u as __pageData,S as default};
